targets.clientTransformScript:
javascript(function evaluateEvent({
    api,
    event
}) {
    const isConfigContext = api.context.props.nowUxfParentPageComponentId !== undefined;
    if (isConfigContext) {
        return {
            route: null,
            fields: {
                table: event.payload.table,
                sysId: event.payload.sys_id
            },
            params: event.payload.params,
            redirect: null,
            passiveNavigation: null,
            title: null,
            multiInstField: event.payload.multiInstField,
            targetRoute: null,
            external: {
                url: `/now/clone/ui/record/${event.payload.table}/${event.payload.sys_id}`,
                newTab: true
            }
        };
    }
    return {
        route: 'record',
        fields: {
            table: event.payload.table,
            sysId: event.payload.sys_id
        },
        params: event.payload.params,
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: event.payload.multiInstField,
        targetRoute: null,
        external: null
    };
})

